# region: gather
def gather(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: intake
def intake(xs, offset=4):
    return [v + offset for v in xs]

# region: emit
def emit(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: render
def render(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (min(xs) - min(xs)) if xs else 0}

# region: digest
def digest(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return digest(render(emit(intake(gather(raw)))))

